INSERT OR IGNORE INTO health_knowledge (id,title,topic,body,source_organization,source_url,approval_status) VALUES
('H101','An toàn thực phẩm','health','Năm nguyên tắc an toàn thực phẩm: giữ sạch, tách sống và chín, nấu kỹ, giữ nhiệt độ an toàn, sử dụng nước và nguyên liệu an toàn.','WHO','https://www.who.int/teams/nutrition-and-food-safety/food-safety-and-quality/five-keys-to-safer-food','needs_review'),
('H102','Hoạt động thể chất','health','Hoạt động thể chất thường xuyên hỗ trợ sức khỏe tim mạch, cơ xương và tinh thần. Khuyến nghị cần phù hợp tuổi và tình trạng sức khỏe.','WHO','https://www.who.int/news-room/fact-sheets/detail/physical-activity','needs_review');
